import { API_URL, API_KEY } from './config.js';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = { get(k){try{return JSON.parse(localStorage.getItem(k))}catch{return null}}, set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Il browser non può salvare il rientro automatico. Mantieni questa pagina aperta.')}} };
const letters = ['A','B','C','D'];
const params = new URLSearchParams(location.search);
let role = params.get('role') || 'home', pin = params.get('pin') || '', secret = '', state = null, offset = 0;
let polling = false, busy = false, answerPending = false, stopped = false, lastTime = 0, fingerprints = {}, boardMode = 'total', stageKey = '', sound = storage.get('cerv:sound') || false, audio;
let joinMode = role === 'display' ? 'display' : 'player';
function toast(message){const el=$('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.style.display='none',5000)}
function connection(label,error=false){$('#connection').textContent=label;$('#connection').classList.toggle('error',error)}
function beep(kind='click'){
 if(!sound)return;
 try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.value=kind==='correct'?740:kind==='wrong'?170:kind==='tick'?480:600;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.13);o.start();o.stop(audio.currentTime+.15)}catch{}
}
function initSound(){ $('#sound').textContent=sound?'Audio on':'Audio off';$('#sound').setAttribute('aria-pressed',String(sound)) }
$('#sound').onclick=()=>{sound=!sound;storage.set('cerv:sound',sound);initSound();beep()};initSound();
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Schermo intero non disponibile su questo dispositivo.')}};
function openDialog(html){$('#modal-content').innerHTML=`<div class="dialog-body">${html}</div>`;$('#modal').showModal()}
async function rpc(action,data={}){
 const started=Date.now();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);
 try{const r=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'application/json',apikey:API_KEY,Authorization:`Bearer ${API_KEY}`},body:JSON.stringify({action,data}),signal:controller.signal});const text=await r.text();let d;try{d=JSON.parse(text)}catch{throw Error('Il servizio non risponde. Riprova tra qualche secondo.')}
 if(!r.ok||d.error)throw Error(d.error||d.message||'Il servizio non risponde. Riprova.');if(d.serverTime){offset=Date.parse(d.serverTime)-(started+Date.now())/2}return d;
 }catch(e){if(e.name==='AbortError')throw Error('La connessione impiega troppo tempo. Riprova.');if(e instanceof TypeError)throw Error('Connessione assente. Controlla la rete e riprova.');throw e}finally{clearTimeout(timeout)}
}
function baseData(){return {pin,role,secret}}
function accept(d){if(Date.parse(d.serverTime)<lastTime)return;lastTime=Date.parse(d.serverTime);state=d;connection('Connesso');renderState();updateTimer()}
async function poll(){if(stopped)return;if(!busy&&!polling){polling=true;try{accept(await rpc('state',baseData()))}catch(e){connection('Riconnessione…',true);if(!state){$('#app').innerHTML=`<div class="skeleton"><h2>${esc(e.message)}</h2><p class="muted">PIN ${esc(pin)}</p><button id="retry">Riprova</button><a class="link" href="./">Torna all’ingresso</a></div>`;$('#retry').onclick=()=>{rpc('state',baseData()).then(accept).catch(e=>toast(e.message))}}}finally{polling=false}}if(!stopped)setTimeout(poll,document.hidden?3000:1000)}
async function command(command,extra={}){if(busy)return;busy=true;updateButtons();try{const d=await rpc('host',{...baseData(),command,...extra});accept(d);beep();return true}catch(e){toast(e.message);return false}finally{busy=false;updateButtons()}}
function changePart(id,html){if(fingerprints[id]===html)return;fingerprints[id]=html;const el=$('#'+id);if(el)el.innerHTML=html}
function home(){
 document.body.className='';
 const last=storage.get('cerv:last-host');const resume=last&&new Date(last.expiresAt)>new Date();
 $('#app').innerHTML=`<section class="home-intro"><div class="eyebrow">Il quiz, tutti insieme</div><h1>La domanda sullo schermo.<br><span>La sfida nelle tue mani.</span></h1><p>Un conduttore, una TV e i telefoni dei giocatori. Crea una stanza o inserisci il PIN per partecipare.</p></section><div class="home-grid"><section class="panel"><div class="panel-head"><h2>Organizza un quiz</h2><span class="number">01</span></div><p>Gestisci domande, tempo e punteggi. Lo schermo TV si apre con un link dedicato.</p><form id="create-form" class="form-stack"><label>Nome della serata<input name="title" maxlength="50" value="Serata quiz" required></label><button class="primary" type="submit">Crea stanza</button></form></section><section class="panel"><div class="panel-head"><h2>Entra nella stanza</h2><span class="number">02</span></div><div class="choices"><button id="mode-player" class="${joinMode==='player'?'selected':''}">Giocatore</button><button id="mode-display" class="${joinMode==='display'?'selected':''}">Schermo TV</button></div><form id="join-form" class="form-stack"><label>PIN della stanza<input name="pin" class="pin-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" value="${esc(pin)}" required></label><label id="name-label" ${joinMode==='display'?'hidden':''}>Il tuo nome<input name="name" maxlength="30" autocomplete="nickname" value="${esc(storage.get('cerv:name')||'')}" placeholder="Come ti chiami?" ${joinMode==='player'?'required':''}></label><button type="submit" class="primary">${joinMode==='display'?'Apri schermo':'Entra e gioca'}</button></form></section></div>${resume?`<div class="resume"><div><strong>Riprendi la tua serata</strong><p class="muted">Stanza ${esc(last.pin)} · ${esc(last.title)}</p></div><button id="resume-host">Apri controllo</button></div>`:''}<div class="steps"><span><b>1.</b>Crea la stanza</span><span><b>2.</b>Apri la TV</span><span><b>3.</b>Condividi il PIN</span></div>`;
 const rememberForm=()=>{pin=$('#join-form input[name=pin]').value;storage.set('cerv:name',$('#join-form input[name=name]').value)};$('#mode-player').onclick=()=>{rememberForm();joinMode='player';home()};$('#mode-display').onclick=()=>{rememberForm();joinMode='display';home()};
 if(resume)$('#resume-host').onclick=()=>navigate('host',last.pin);
 $('#create-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent='Creazione…';const title=new FormData(e.target).get('title');try{const d=await rpc('create',{title});storage.set(`cerv:host:${d.pin}`,d.secret);storage.set('cerv:last-host',{...d,title});navigate('host',d.pin)}catch(e){toast(e.message);btn.disabled=false;btn.textContent='Crea stanza'}};
 $('#join-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),vpin=String(form.get('pin')).trim();if(!/^\d{6}$/.test(vpin))return toast('Inserisci un PIN di 6 cifre');const btn=e.submitter;btn.disabled=true;try{if(joinMode==='display'){await rpc('state',{pin:vpin,role:'display'});navigate('display',vpin)}else{const d=await rpc('join',{pin:vpin,name:String(form.get('name')).trim(),secret:storage.get(`cerv:player:${vpin}`)?.secret||''});storage.set(`cerv:player:${vpin}`,d);storage.set('cerv:name',d.name);navigate('player',vpin)}}catch(e){toast(e.message);btn.disabled=false}};
}
function navigate(r,p){location.href=`./?role=${r}&pin=${encodeURIComponent(p)}`}
function roomHeading(label){return `<div class="room-heading"><div><div class="eyebrow">${label}</div><h1 id="room-title"></h1></div><div class="pin-badge"><span class="muted">PIN stanza</span><strong>${esc(pin)}</strong></div></div>`}
function setupHost(){
 document.body.className='host';$('#app').innerHTML=roomHeading('Controllo conduttore')+`<div class="host-grid"><div class="host-left"><section><div id="stage" class="stage"></div><div class="controls"><button id="start" class="primary">Avvia quiz</button><button id="reveal">Mostra risposta</button><button id="next">Prossima domanda</button><button id="end" class="danger">Termina</button></div><div class="subline"><span id="answer-stats"></span><button id="open-tv" class="icon-btn">Apri schermo TV</button></div></section><section class="panel"><div class="panel-head"><h2>Domande</h2><span id="q-count" class="pill"></span></div><div class="files"><div><strong>Il tuo pacchetto quiz</strong><p>JSON · 4 opzioni · massimo 100 domande</p></div><label class="file-btn"><span class="icon-btn">Importa JSON</span><input id="upload" type="file" accept=".json,application/json" aria-label="Importa domande JSON"></label></div><div class="secondary-controls"><button id="select-questions" class="icon-btn">Scegli domande</button><button id="export-questions" class="icon-btn">Esporta pacchetto</button><button id="share" class="icon-btn">Condividi stanza</button></div></section><section class="panel"><div class="panel-head"><h2>Regole della serata</h2><span class="muted">Prima di iniziare</span></div><form id="settings-form"><div class="config-grid"><label>Tempo, secondi<input id="duration" type="number" min="5" max="90" required></label><label>Punti massimi<input id="maxPoints" type="number" min="100" max="10000" required></label><label>Penalità errore<input id="penalty" type="number" min="0" max="5000" required></label><label>Salti gratuiti<input id="freeSkips" type="number" min="0" max="100" required></label></div><div class="checks"><label class="check"><input id="autoAdvance" type="checkbox">Avanzamento automatico</label><label class="check"><input id="leaderboard" type="checkbox">Classifica sullo schermo</label></div><div class="secondary-controls"><button id="save-settings" type="submit">Salva regole</button><button id="reset" type="button" class="danger">Azzera punteggi</button></div></form></section></div><aside class="panel"><div class="panel-head"><h2>Giocatori</h2><span id="player-count" class="pill"></span></div><div class="round-toggle"><button id="board-total" class="selected">Totale</button><button id="board-round">Questa manche</button></div><div id="board" class="board"></div><div class="secondary-controls"><button id="fullboard" class="icon-btn">Mostra classifica TV</button><button id="export-board" class="icon-btn">Esporta risultati</button></div></aside></div>`;
 $('#start').onclick=()=>command('start');$('#reveal').onclick=()=>command('reveal');$('#next').onclick=()=>command('next');
 $('#end').onclick=()=>confirmAction('Terminare la partita?','La domanda aperta verrà conteggiata e comparirà la classifica finale.',()=>command('end'));
 $('#open-tv').onclick=()=>window.open(`./?role=display&pin=${pin}`,'cervellone-tv','noopener');
 $('#share').onclick=showShare;
 $('#fullboard').onclick=()=>command('fullboard',{visible:!state.fullboard});
 $('#reset').onclick=()=>confirmAction('Azzerare tutti i punteggi?','I giocatori resteranno nella stanza. Il quiz tornerà in attesa.',()=>command('reset'));
 $('#board-total').onclick=()=>setBoardMode('total');$('#board-round').onclick=()=>setBoardMode('round');
 $('#settings-form').onsubmit=async e=>{e.preventDefault();const extra={};for(const key of ['duration','maxPoints','penalty','freeSkips'])extra[key]=Number($('#'+key).value);for(const key of ['autoAdvance','leaderboard'])extra[key]=$('#'+key).checked;if(await command('settings',extra))toast('Regole salvate')};
 $('#upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1800000)throw Error('File troppo grande (massimo 1,8 MB)');const raw=JSON.parse(await file.text());const qs=Array.isArray(raw)?raw:raw.questions;if(!Array.isArray(qs)||!qs.length)throw Error('Il JSON non contiene domande');if(qs.length>100){importSelection(qs,file.name)}else if(await command('upload',{questions:qs})){toast(`${qs.length} domande caricate`)}}catch(e){toast(e.message)}finally{$('#upload').value=''}};
 $('#select-questions').onclick=()=>importSelection(state.questions,'Pacchetto della stanza');
 $('#export-questions').onclick=()=>download('Cervellone-domande.json',JSON.stringify(state.questions,null,2),'application/json');
 $('#export-board').onclick=()=>{const csv='Nome,Punti totali,Punti manche\n'+state.board.map(p=>[p.name,p.score,p.roundScore].map(csvCell).join(',')).join('\n');download('Cervellone-risultati.csv','\ufeff'+csv,'text/csv')};
}
function csvCell(v){let s=String(v);if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function confirmAction(title,text,fn){openDialog(`<h2>${title}</h2><p>${text}</p><button id="confirm-action" class="primary">Conferma</button>`);$('#confirm-action').onclick=async()=>{$('#modal').close();await fn()}}
function showShare(){const playerURL=new URL(`./?role=player&pin=${pin}`,location.href).href;const tvURL=new URL(`./?role=display&pin=${pin}`,location.href).href;openDialog(`<h2>Invita i giocatori</h2><p>Apri il link sul telefono oppure inserisci il PIN <strong>${pin}</strong>.</p><div class="code">${esc(playerURL)}</div><button id="copy-link" class="primary">Copia link giocatori</button><p>Link per TV o proiettore</p><div class="code">${esc(tvURL)}</div><p>La stanza resta disponibile per 24 ore. Il controllo conduttore rimane sul dispositivo che l’ha creata.</p>`);$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(playerURL);toast('Link copiato')}catch{toast('Seleziona e copia il link mostrato')}}}
function importSelection(qs,title){
 if(!['lobby','final'].includes(state.phase))return toast('Termina la partita prima di cambiare domande');
 const categories=[...new Set(qs.map(q=>q.category||'Senza categoria'))].sort();
 openDialog(`<h2>${esc(title)}</h2><p>${qs.length} domande disponibili. Scegli un gruppo e quante usarne.</p><label>Categoria<select id="filter-category"><option value="">Tutte</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Numero domande<input id="filter-count" type="number" min="1" max="100" value="${Math.min(20,qs.length)}"></label><label class="check"><input id="shuffle" type="checkbox" checked>Mescola ordine e risposte</label><p id="filter-available" class="muted"></p><button id="import-selected" class="primary">Usa queste domande</button>`);
 const available=()=>qs.filter(q=>!$('#filter-category').value||(q.category||'Senza categoria')===$('#filter-category').value);
 const count=()=>$('#filter-available').textContent=`${available().length} domande nella selezione`;count();$('#filter-category').onchange=count;
 $('#import-selected').onclick=async()=>{let selected=structuredClone(available());const num=Number($('#filter-count').value);if(!Number.isInteger(num)||num<1||num>100)return toast('Scegli da 1 a 100 domande');if(!selected.length)return toast('Nessuna domanda disponibile');if($('#shuffle').checked){shuffle(selected);selected=selected.slice(0,num).map(q=>{const zipped=q.options.map((text,index)=>({text,index}));shuffle(zipped);return {...q,options:zipped.map(o=>o.text),correctIndex:zipped.findIndex(o=>o.index===q.correctIndex)}})}else selected=selected.slice(0,num);if(await command('upload',{questions:selected})){$('#modal').close();toast(`${selected.length} domande pronte`)}};
}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}}
function setBoardMode(mode){boardMode=mode;$('#board-total').classList.toggle('selected',mode==='total');$('#board-round').classList.toggle('selected',mode==='round');renderBoard()}
function setupDisplay(){document.body.className='display';$('#app').innerHTML=`<div id="display-layout" class="display-layout"><section id="stage" class="stage"></section><aside id="display-board" class="panel"><div class="panel-head"><h2>Classifica</h2><span class="pill">Live</span></div><div id="board" class="board"></div></aside></div>`}
function setupPlayer(){document.body.className='player';$('#app').innerHTML=`<div class="player-heading"><div><div class="eyebrow">PIN ${esc(pin)}</div><h1 id="my-name"></h1></div><div class="score-chip"><span class="muted">Il tuo punteggio</span><strong id="my-score">0</strong></div></div><div id="player-message" class="player-message" aria-live="polite"></div><div class="timer-track"><div id="player-timer-fill" class="timer-fill"></div></div><div class="pads" style="margin-top:22px">${letters.map((l,i)=>`<button class="pad ${l.toLowerCase()}" id="pad-${i}" data-index="${i}" disabled aria-label="Risposta ${l}">${l}</button>`).join('')}</div><div class="player-foot"><span id="player-progress"></span><span id="player-timer" class="countdown"></span></div><div id="player-final"></div>`;for(let i=0;i<4;i++)$('#pad-'+i).onclick=()=>sendAnswer(i)}
async function sendAnswer(choice){if(answerPending||!state||state.phase!=='question'||state.mine?.choice!=null)return;answerPending=true;updatePads();try{const d=await rpc('answer',{...baseData(),idx:state.idx,round:state.round,choice});accept(d);beep()}catch(e){toast(e.message);try{accept(await rpc('state',baseData()))}catch{connection('Riconnessione…',true)}}finally{answerPending=false;updatePads()}}
function phaseLabel(){return {lobby:'In attesa',precount:'Preparati',question:'Domanda aperta',reveal:'Risultato',final:'Partita conclusa'}[state.phase]||''}
function renderStage(){
 const s=state,q=s.question,display=role==='display';const count=s.idx>=0?`Domanda ${s.idx+1} / ${s.total}`:`${s.total} domande pronte`;
 const meta=`<div class="stage-meta"><span>${esc(s.title)} · ${count}</span><span class="pill">${phaseLabel()}</span></div>`;
 let html=meta;
 if(s.fullboard){html+=`<div class="stage-empty"><div class="eyebrow">Classifica generale</div>${s.board.slice(0,10).map((p,i)=>`<div class="board-row"><span class="rank">${i+1}</span><span class="board-name">${esc(p.name)}</span><span class="points">${p.score.toLocaleString('it-IT')}</span></div>`).join('')}</div>`}
 else if(s.phase==='lobby'){html+=`<div class="stage-empty"><h2>${display?'Entra nella sfida':'La tua stanza è pronta'}</h2><div class="big-pin">${s.pin}</div><p class="join-note">${display?'Apri il link sul telefono e inserisci il PIN.':'Invita i giocatori, poi avvia il quiz.'}</p><span class="muted">${s.players} ${s.players===1?'giocatore collegato':'giocatori nella stanza'}</span></div>`}
 else if(s.phase==='precount'){html+=`<div class="stage-empty"><h2>Pronti per la prossima?</h2><div class="big-count" data-timer></div><p class="muted">Guarda lo schermo. Scegli sul telefono.</p></div>`}
 else if(s.phase==='final'){const winner=s.board[0];html+=`<div class="stage-empty"><div class="eyebrow">${winner?'Primo in classifica':'Quiz concluso'}</div><div class="final-winner">${esc(winner?.name||'Alla prossima sfida')}</div>${winner?`<h2>${winner.score.toLocaleString('it-IT')} punti</h2>`:''}<p class="muted">${display?'Grazie per aver giocato.':'Avvia un’altra manche oppure cambia le domande.'}</p></div>`}
 else if(q){html+=`<div class="stage-meta"><span>${esc(q.category||'Quiz')} · ${esc(q.difficulty||'')}</span><span class="countdown" data-timer></span></div><h2>${esc(q.question)}</h2><div class="answers">${q.options.map((o,i)=>`<div class="answer ${letters[i].toLowerCase()} ${s.phase==='reveal'?(i===q.correctIndex?'correct':'faded'):''}"><b>${letters[i]}</b><span>${esc(o)}</span>${s.phase==='reveal'&&i===q.correctIndex?'<span aria-label="Corretta">✓</span>':''}</div>`).join('')}</div>${s.phase==='question'?'<div class="timer-track"><div id="stage-timer-fill" class="timer-fill"></div></div>':''}`}
 changePart('stage',html);
}
function renderBoard(){if(!$('#board'))return;const board=state.board.slice();if(boardMode==='round'&&role==='host')board.sort((a,b)=>b.roundScore-a.roundScore||a.name.localeCompare(b.name));let html=board.length?board.map((p,i)=>`<div class="board-row"><span class="rank">${i+1}</span><span class="board-name">${esc(p.name)}${role==='host'?`<small>${p.online?'Collegato':'Connessione assente'}${state.phase==='question'&&p.answered?' · ha risposto':''}</small>`:''}</span><span class="points">${(boardMode==='round'&&role==='host'?p.roundScore:p.score).toLocaleString('it-IT')}</span>${role==='host'?`<button class="board-tools" data-player="${p.id}" aria-label="Gestisci ${esc(p.name)}">···</button>`:''}</div>`).join(''):'<div class="empty">Nessun giocatore per ora.<br>Condividi il PIN della stanza.</div>';changePart('board',html);if(role==='host')document.querySelectorAll('[data-player]').forEach(el=>el.onclick=()=>managePlayer(el.dataset.player))}
function managePlayer(id){const p=state.board.find(p=>p.id===id);openDialog(`<h2>Gestisci giocatore</h2><label>Nome<input id="edit-name" maxlength="30" value="${esc(p.name)}"></label><label>Punti totali<input id="edit-score" type="number" min="0" max="1000000" value="${p.score}"></label><button id="save-player" class="primary">Salva modifiche</button><button id="kick-player" class="danger" ${['lobby','final'].includes(state.phase)?'':'disabled'}>Rimuovi dalla stanza</button>`);$('#save-player').onclick=async()=>{const name=$('#edit-name').value.trim(),score=Number($('#edit-score').value);if(!name||name.length>30||!Number.isInteger(score)||score<0||score>1000000)return toast('Controlla nome e punteggio');if(name!==p.name&&!(await command('rename',{playerId:id,name})))return;if(score!==p.score&&!(await command('score',{playerId:id,score})))return;$('#modal').close()};$('#kick-player').onclick=async()=>{if(await command('kick',{playerId:id}))$('#modal').close()}}
function renderPlayer(){const s=state,m=s.mine;if(!m)return;$('#my-name').textContent=m.name;$('#my-score').textContent=m.score.toLocaleString('it-IT');$('#player-progress').textContent=s.idx<0?'In attesa del conduttore':`Domanda ${s.idx+1} di ${s.total}`;
 let html='';if(s.phase==='lobby')html='<h2>Sei nella partita.</h2><p class="muted">Guarda la TV. Il conduttore sta per iniziare.</p>';
 if(s.phase==='precount')html='<h2>Preparati…</h2><p class="muted">Le risposte appariranno sullo schermo.</p>';
 if(s.phase==='question')html=m.choice!=null?`<h2>Risposta ${letters[m.choice]} registrata.</h2><p class="muted">Aspetta il risultato sullo schermo.</p>`:answerPending?'<h2>Invio in corso…</h2><p class="muted">Attendi la conferma.</p>':'<h2>Qual è la risposta?</h2><p class="muted">Guarda la TV e tocca il colore.</p>';
 if(s.phase==='reveal'){const result=m.result,delta=m.delta;html=`<h2 class="${result==='correct'?'result-correct':['wrong','missed'].includes(result)?'result-wrong':''}">${result==='correct'?'Risposta corretta!':result==='wrong'?'Risposta sbagliata':result==='missed'?'Tempo scaduto':'Hai saltato la domanda'}</h2><p class="muted">${delta>0?'+':''}${delta||0} punti · Risposta corretta: ${letters[s.correctIndex]}</p>`}
 if(s.phase==='final')html=`<h2>Partita conclusa</h2><p class="muted">Hai totalizzato ${m.score.toLocaleString('it-IT')} punti.</p>`;
 changePart('player-message',html);changePart('player-final',s.phase==='final'?`<section class="panel" style="margin-top:25px"><h2>Classifica finale</h2><div class="board" style="margin-top:18px">${s.board.map((p,i)=>`<div class="board-row"><span class="rank">${i+1}</span><span class="board-name">${esc(p.name)}</span><span class="points">${p.score}</span></div>`).join('')}</div></section>`:'');updatePads();
}
function updatePads(){if(role!=='player'||!state)return;const m=state.mine;const remaining=Date.parse(state.deadline)-(Date.now()+offset);for(let i=0;i<4;i++){const b=$('#pad-'+i);if(!b)continue;b.disabled=state.phase!=='question'||remaining<=0||m?.choice!=null||answerPending;b.classList.toggle('selected',m?.choice===i);b.classList.toggle('correct',state.phase==='reveal'&&state.correctIndex===i)}}
function updateButtons(){if(role!=='host'||!state)return;const phase=state.phase;$('#start').disabled=busy||!['lobby','final'].includes(phase)||state.players===0||!state.total;$('#start').textContent=phase==='final'?'Avvia altra manche':'Avvia quiz';$('#reveal').disabled=busy||phase!=='question';$('#next').disabled=busy||phase!=='reveal';$('#end').disabled=busy||['lobby','final'].includes(phase);const edit=!busy&&['lobby','final'].includes(phase);for(const id of ['save-settings','reset','upload','select-questions'])$('#'+id).disabled=!edit;$('#fullboard').textContent=state.fullboard?'Nascondi classifica TV':'Mostra classifica TV'}
function renderState(){const key=`${state.round}:${state.idx}:${state.phase}`;if(key!==stageKey){if(stageKey){beep(state.phase==='reveal'?(state.mine?.result==='correct'?'correct':'wrong'):state.phase==='question'?'click':'tick')}stageKey=key}
 if(role==='host'){if(!$('#stage'))setupHost();$('#room-title').textContent=state.title;$('#q-count').textContent=`${state.total} domande`;$('#player-count').textContent=state.players;$('#answer-stats').textContent=state.phase==='question'?`${state.answered} / ${state.players} risposte ricevute`:`${state.players} giocatori · ${phaseLabel()}`;if(!setupHost.configured){populateSettings();setupHost.configured=true}renderStage();renderBoard();updateButtons()}
 if(role==='display'){if(!$('#stage'))setupDisplay();const show=state.settings.leaderboard||state.phase==='final';$('#display-layout').classList.toggle('no-board',!show);$('#display-board').hidden=!show;renderStage();renderBoard()}
 if(role==='player'){if(!$('#my-name'))setupPlayer();renderPlayer()}
}
function populateSettings(){for(const key of ['maxPoints','penalty','freeSkips'])$('#'+key).value=state.settings[key];$('#duration').value=state.duration;for(const key of ['autoAdvance','leaderboard'])$('#'+key).checked=state.settings[key]}
let lastTick=-1;
function updateTimer(){if(!state)return;const secs=Math.max(0,Math.ceil((Date.parse(state.deadline)-(Date.now()+offset))/1000));const active=['question','precount'].includes(state.phase);document.querySelectorAll('[data-timer]').forEach(el=>{el.textContent=active?secs+(state.phase==='question'?'s':''):'';el.classList.toggle('urgent',state.phase==='question'&&secs<=3)});for(const id of ['stage-timer-fill','player-timer-fill']){const el=$('#'+id);if(el){el.style.width=state.phase==='question'?`${Math.max(0,Math.min(100,100*(Date.parse(state.deadline)-(Date.now()+offset))/(state.duration*1000)))}%`:'0%';el.classList.toggle('urgent',secs<=3)}}if(role==='player'&&$('#player-timer')){$('#player-timer').textContent=active?`${secs}s`:'';$('#player-timer').classList.toggle('urgent',secs<=3);updatePads()}if(state.phase==='question'&&secs<=3&&secs>0&&secs!==lastTick){lastTick=secs;beep('tick')}if(!active)lastTick=-1}
setInterval(updateTimer,100);
document.addEventListener('visibilitychange',()=>{if(state&&!document.hidden&&!stopped&&!polling&&!busy)rpc('state',baseData()).then(accept).catch(()=>connection('Riconnessione…',true))});
window.addEventListener('online',()=>connection('Riconnessione…'));window.addEventListener('offline',()=>connection('Offline',true));
async function init(){if(!['host','player','display'].includes(role)||!/^\d{6}$/.test(pin)){home();return}
 if(role==='host'){secret=storage.get(`cerv:host:${pin}`)||'';if(!secret){$('#app').innerHTML='<div class="skeleton"><h2>Controllo riservato al creatore della stanza</h2><p class="muted">Apri questo link sul dispositivo con cui hai creato la stanza.</p><a href="./" class="link">Torna all’ingresso</a></div>';return}}
 if(role==='player'){secret=storage.get(`cerv:player:${pin}`)?.secret||'';if(!secret){joinMode='player';home();return}}
 $('#app').innerHTML='<div class="skeleton"><div class="spinner"></div><p class="muted">Connessione alla stanza…</p></div>';await poll()}
init();
